/*Table structure for table `adm_district` */

DROP TABLE IF EXISTS `adm_district`;

CREATE TABLE `adm_district` (
  `id` tinyint(3) NOT NULL,
  `district_code` char(2) NOT NULL,
  `district` varchar(50) NOT NULL,
  `districtDz` varchar(100) NOT NULL,
  `status` tinyint(11) NOT NULL DEFAULT 1,
  `coordinates` longtext DEFAULT NULL,
  `author` int(11) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UNIQUE` (`district_code`)
