/*Table structure for table `adm_intl_countries` */

DROP TABLE IF EXISTS `adm_intl_countries`;

CREATE TABLE `adm_intl_countries` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `num_code` int(3) DEFAULT NULL,
  `alpha_2` char(2) NOT NULL,
  `alpha_3` char(3) NOT NULL,
