/*Table structure for table `adm_transaction_flow` */

DROP TABLE IF EXISTS `adm_transaction_flow`;

CREATE TABLE `adm_transaction_flow` (
  `id` int(9) unsigned NOT NULL AUTO_INCREMENT,
  `role_id` int(11) DEFAULT NULL,
  `flow` tinyint(1) NOT NULL,
  `application` int(9) unsigned NOT NULL,
  `actor` tinyint(2) unsigned NOT NULL COMMENT 'role',
  `activity` int(11) DEFAULT NULL,
  `status` tinyint(2) unsigned NOT NULL,
  `action` varchar(12) NOT NULL,
  `routing` int(11) NOT NULL,
  `routing_status` tinyint(4) NOT NULL,
  `action_performed` tinyint(4) NOT NULL DEFAULT 0,
  `description` text DEFAULT NULL,
  `author` smallint(5) NOT NULL,
  `created` timestamp NULL DEFAULT current_timestamp(),
  `modified` timestamp NULL DEFAULT current_timestamp(),
