/*Table structure for table `ast_asset` */

DROP TABLE IF EXISTS `ast_asset`;

CREATE TABLE `ast_asset` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `asset_type` int(11) NOT NULL,
  `assetid` varchar(100) DEFAULT NULL,
  `code` varchar(50) NOT NULL,
  `name` varchar(100) NOT NULL,
  `region` int(11) DEFAULT NULL,
  `location` int(11) DEFAULT NULL,
  `custodian` int(11) DEFAULT NULL,
  `purchase_date` date DEFAULT '2023-08-29',
  `putin_date` date DEFAULT NULL,
  `asset_value` decimal(12,2) DEFAULT NULL,
  `salvage` decimal(12,2) DEFAULT NULL,
  `depreciable_amount` decimal(12,2) DEFAULT NULL,
  `depreciation` tinyint(1) DEFAULT 0,
  `dep_per_day` decimal(12,3) DEFAULT NULL,
  `usefullife` decimal(12,2) DEFAULT NULL,
  `disposal_amount` decimal(12,2) DEFAULT NULL,
  `disposal_year` year(4) DEFAULT NULL,
  `disposal_date` date DEFAULT '0000-00-00',
  `writeoff_amount` decimal(10,2) DEFAULT NULL,
  `writeoff_date` date DEFAULT NULL,
  `writeoff_year` year(4) DEFAULT NULL,
  `acc_depreciation` decimal(12,2) DEFAULT 0.00,
  `previous_depreciated_amount` decimal(12,2) DEFAULT NULL,
  `net` decimal(12,2) DEFAULT 0.00,
  `status` int(11) DEFAULT 1,
  `author` int(11) DEFAULT NULL,
  `created` timestamp NULL DEFAULT current_timestamp(),
  `modified` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Data for the table `ast_asset` */

