/*Table structure for table `ast_depreciate` */

DROP TABLE IF EXISTS `ast_depreciate`;

CREATE TABLE `ast_depreciate` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `asset` int(11) DEFAULT NULL,
  `year` year(4) DEFAULT NULL,
  `month` int(11) DEFAULT NULL,
  `dep_amount` decimal(10,3) DEFAULT NULL,
  `type` int(11) DEFAULT NULL,
  `ref_no` varchar(100) DEFAULT NULL,
  `net` decimal(10,2) DEFAULT NULL,
  `location` int(10) DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  `author` int(8) DEFAULT NULL,
  `created` timestamp NOT NULL DEFAULT current_timestamp(),
  `modified` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

