/*Table structure for table `fa_transaction_details_log` */

DROP TABLE IF EXISTS `fa_transaction_details_log`;

CREATE TABLE `fa_transaction_details_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `action_type` enum('INSERT','UPDATE','DELETE') DEFAULT NULL,
  `transaction_id` int(11) DEFAULT NULL,
  `old_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `new_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `modified_by` varchar(255) DEFAULT NULL,
  `author` int(11) DEFAULT NULL,
  `modified_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

