/*Table structure for table `po_box_rg` */

DROP TABLE IF EXISTS `po_box_rg`;

CREATE TABLE `po_box_rg` (
  `id` int(4) NOT NULL AUTO_INCREMENT,
  `location` varchar(15) DEFAULT NULL,
  `region` varchar(15) DEFAULT NULL,
  `postbox_no` bigint(15) DEFAULT NULL,
  `post_box_size` int(11) DEFAULT NULL,
  `name` varchar(200) DEFAULT NULL,
  `cid` varchar(30) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `mobile` int(10) DEFAULT NULL,
  `tphone` bigint(10) DEFAULT 0,
  `organisation` varchar(200) DEFAULT NULL,
  `building_no` varchar(100) DEFAULT '0',
  `address` varchar(20) DEFAULT NULL,
  `year` year(4) DEFAULT NULL,
  `registration_date` date DEFAULT NULL,
  `status` int(2) DEFAULT NULL,
  `author` int(10) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `transaction_id` int(11) DEFAULT NULL,
  `cash` enum('1','0') DEFAULT NULL COMMENT '1=cash, 0=bank',
  `journal_no` varchar(100) DEFAULT NULL,
  `ref_no` varchar(100) DEFAULT NULL,
  `key_rate` decimal(13,2) DEFAULT NULL,
  `po_rate` decimal(13,2) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1672 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

