/*Table structure for table `ps_bank_account` */

DROP TABLE IF EXISTS `ps_bank_account`;

CREATE TABLE `ps_bank_account` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL,
  `bank` tinyint(4) NOT NULL,
  `branch` varchar(50) DEFAULT NULL,
  `account` varchar(50) NOT NULL,
  `location` int(10) NOT NULL,
  `acc_type` int(4) DEFAULT NULL,
  `author` int(10) NOT NULL,
  `created` datetime NOT NULL,
  `modified` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=168 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

/*Data for the table `ps_bank_account` */

/*Table structure for table `ps_benefit` */

DROP TABLE IF EXISTS `ps_benefit`;

CREATE TABLE `ps_benefit` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `transaction_id` int(11) DEFAULT NULL,
  `category` int(11) NOT NULL,
  `subhead` int(11) DEFAULT NULL,
  `employee` int(11) DEFAULT NULL COMMENT 'only on semso',
  `requested_amt` decimal(10,2) NOT NULL,
  `relationship` int(11) DEFAULT NULL COMMENT 'only on semso',
  `subject` varchar(200) DEFAULT NULL,
  `description` varchar(500) DEFAULT NULL,
  `approved_amt` decimal(10,2) DEFAULT NULL,
  `location` int(11) NOT NULL COMMENT 'The location of the benefit application',
  `status` int(11) NOT NULL,
  `author` int(11) NOT NULL,
  `created` timestamp NOT NULL DEFAULT current_timestamp(),
  `modified` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Data for the table `ps_benefit` */

/*Table structure for table `ps_benefit_emi` */

DROP TABLE IF EXISTS `ps_benefit_emi`;

CREATE TABLE `ps_benefit_emi` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `location` int(11) NOT NULL,
  `employee` int(11) NOT NULL,
  `sub_head` int(11) NOT NULL,
  `year` year(4) NOT NULL,
  `month` tinyint(4) NOT NULL,
  `benefit_amount` decimal(12,3) NOT NULL,
  `emi` decimal(12,3) NOT NULL,
  `ref_no` varchar(100) NOT NULL,
  `status` int(11) NOT NULL,
  `author` int(11) NOT NULL,
  `created` datetime NOT NULL,
  `modified` datetime NOT NULL,
  PRIMARY KEY (`id`,`location`,`employee`,`sub_head`,`year`,`month`,`benefit_amount`,`emi`,`ref_no`,`status`,`author`,`created`,`modified`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Data for the table `ps_benefit_emi` */

/*Table structure for table `ps_benefit_history` */

DROP TABLE IF EXISTS `ps_benefit_history`;

CREATE TABLE `ps_benefit_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date DEFAULT NULL,
  `transaction_id` bigint(20) DEFAULT NULL,
  `category` int(11) DEFAULT NULL,
  `subhead` int(11) DEFAULT NULL,
  `employee` int(11) NOT NULL,
  `requested_amt` decimal(10,2) NOT NULL,
  `subject` varchar(200) DEFAULT NULL,
  `description` varchar(200) DEFAULT NULL,
  `approved_amt` decimal(10,2) DEFAULT NULL,
  `location` int(11) DEFAULT NULL COMMENT 'The location of the benefit application',
  `status` int(11) DEFAULT NULL,
  `author` int(11) DEFAULT NULL,
  `created` timestamp NOT NULL DEFAULT current_timestamp(),
  `modified` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Data for the table `ps_benefit_history` */

/*Table structure for table `ps_cash_account` */

DROP TABLE IF EXISTS `ps_cash_account`;

CREATE TABLE `ps_cash_account` (
  `id` bigint(4) NOT NULL AUTO_INCREMENT,
  `region` int(11) DEFAULT NULL,
  `location` int(4) DEFAULT NULL,
  `cash_account_code` varchar(50) DEFAULT NULL,
  `cash_account_name` varchar(50) DEFAULT NULL,
  `acc_type` int(4) DEFAULT NULL,
  `author` int(4) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=147 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Data for the table `ps_cash_account` */

/*Table structure for table `ps_class` */

DROP TABLE IF EXISTS `ps_class`;

CREATE TABLE `ps_class` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL,
  `name` varchar(50) NOT NULL,
  `author` int(10) NOT NULL,
  `created` datetime NOT NULL,
  `modified` datetime NOT NULL,
  PRIMARY KEY (`id`)
