/*Table structure for table `ps_transaction` */

DROP TABLE IF EXISTS `ps_transaction`;

CREATE TABLE `ps_transaction` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `voucher_date` date NOT NULL,
  `voucher_type` int(10) NOT NULL,
  `region` int(11) DEFAULT NULL,
  `against` int(11) DEFAULT 0,
  `against_vid` varchar(100) DEFAULT NULL,
  `doc_id` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `doc_type` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `voucher_no` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `voucher_amount` decimal(20,2) NOT NULL,
  `currency` int(11) DEFAULT 1,
  `bank_ref_type` int(4) DEFAULT NULL,
  `cheque_no` varchar(20) DEFAULT NULL,
  `remark` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `ref_no` varchar(255) DEFAULT NULL,
  `reconcile_status` tinyint(1) DEFAULT 0,
  `status` tinyint(4) NOT NULL DEFAULT 0,
  `author` bigint(20) NOT NULL,
  `created` datetime NOT NULL,
  `modified` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Data for the table `ps_transaction` */

/*Table structure for table `ps_transaction_details` */

DROP TABLE IF EXISTS `ps_transaction_details`;

CREATE TABLE `ps_transaction_details` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `reconcile` int(11) DEFAULT 0,
  `reconcile_date` date DEFAULT NULL,
  `transaction` bigint(20) NOT NULL,
  `voucher_dates` date DEFAULT NULL,
  `voucher_types` int(11) DEFAULT NULL,
  `location` int(10) NOT NULL,
  `activity` int(11) DEFAULT NULL,
  `against` int(11) DEFAULT 0,
  `head` int(20) NOT NULL,
  `sub_head` bigint(20) NOT NULL,
  `bank_ref_type` varchar(10) DEFAULT NULL,
  `cheque_no` varchar(100) DEFAULT NULL,
  `debit` decimal(20,2) NOT NULL,
  `credit` decimal(20,2) NOT NULL,
  `currency` int(11) DEFAULT 1,
  `rate` decimal(12,3) DEFAULT 0.000,
  `debit_sdr` decimal(12,3) DEFAULT 0.000,
  `credit_sdr` decimal(21,3) DEFAULT 0.000,
  `against_status` int(6) DEFAULT NULL,
  `ref_no` varchar(20) DEFAULT NULL,
  `type` tinyint(4) DEFAULT NULL COMMENT '1-user input, 2-system generated',
  `status` int(11) DEFAULT NULL,
  `author` bigint(20) NOT NULL,
  `created` datetime NOT NULL,
  `modified` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `HEAD_ID` (`head`),
  KEY `SUB_HEAD_ID` (`sub_head`),
  KEY `TRANSACTION_ID` (`transaction`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

/*Data for the table `ps_transaction_details` */

