/*Table structure for table `sys_attendance` */

DROP TABLE IF EXISTS `sys_attendance`;

CREATE TABLE `sys_attendance` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user` int(11) NOT NULL,
  `ip_address1` varchar(200) NOT NULL,
  `entry` time DEFAULT NULL,
  `exit` time DEFAULT NULL,
  `ip_address2` varchar(200) DEFAULT NULL,
  `date` date NOT NULL,
  `location` int(11) DEFAULT NULL,
  `late_reason` varchar(200) DEFAULT NULL,
  `early_reason` varchar(200) DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

