/*Table structure for table `sys_role_process` */

DROP TABLE IF EXISTS `sys_role_process`;

CREATE TABLE `sys_role_process` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `role` int(11) NOT NULL,
  `process` int(11) NOT NULL,
  `location` enum('0','1') NOT NULL DEFAULT '0',
  `activity` enum('0','1') NOT NULL DEFAULT '0',
  `only_if_creator` enum('0','1') NOT NULL DEFAULT '0',
  `status` enum('0','1') NOT NULL DEFAULT '0',
  `permission_level` text DEFAULT NULL COMMENT 'sys_process, col:permission_level',
  `author` int(11) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UNIQUE` (`role`,`process`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

