/*Table structure for table `tp_transport` */

DROP TABLE IF EXISTS `tp_transport`;

CREATE TABLE `tp_transport` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `license_plate` varchar(25) NOT NULL,
  `region` int(11) DEFAULT NULL,
  `location` int(11) DEFAULT NULL,
  `class` int(11) NOT NULL DEFAULT 0,
  `vehicle_code` varchar(25) NOT NULL DEFAULT '0',
  `registered_date` date DEFAULT NULL,
  `acquisition_date` date DEFAULT NULL,
  `make` int(11) DEFAULT 0,
  `group` int(11) DEFAULT NULL,
  `model` varchar(40) DEFAULT NULL,
  `source_of_fund` varchar(40) DEFAULT NULL,
  `naked_vehicle_value` decimal(10,2) DEFAULT 0.00,
  `final_vehicle_value` decimal(10,2) DEFAULT 0.00,
  `engine_no` varchar(25) DEFAULT '0',
  `chasis_no` varchar(25) DEFAULT '0',
  `odometer_value` decimal(10,2) DEFAULT 0.00,
  `fuel_type` tinyint(4) DEFAULT 0,
  `tank_capacity` decimal(10,2) DEFAULT 0.00,
  `color` varchar(25) DEFAULT NULL,
  `no_of_wheels` int(11) DEFAULT 0,
  `rim_size` varchar(20) DEFAULT NULL,
  `insurance_company` varchar(50) DEFAULT NULL,
  `policy_no` varchar(50) DEFAULT NULL,
  `sum_assured` decimal(10,2) DEFAULT NULL,
  `fuel_supplier` varchar(25) DEFAULT NULL,
  `supplier_book_no` varchar(25) DEFAULT NULL,
  `advance_ceiling` decimal(10,2) DEFAULT 0.00,
  `remarks` varchar(50) DEFAULT NULL,
  `status` tinyint(4) DEFAULT 0,
  `author` int(11) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

