DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `trigger_advancesalary_insert` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'localhost' */ /*!50003 TRIGGER `trigger_advancesalary_insert` AFTER INSERT ON `fa_advance_salary` FOR EACH ROW BEGIN
